function IdolLive3D_SuperTimeLineStateV2:Init( idolLive3D_InteractiveManager_, roleAnimator_, timelineTFMaps_, interactiveState_ )

    self.idolLive3D_InteractiveManager = idolLive3D_InteractiveManager_
    self.mainForRuntime = self.idolLive3D_InteractiveManager.idolLive3D_Main
    self.uiMain = self.mainForRuntime.uiMain -- !!! sml Package 中是没有的...
    self.roleIKMgr = self.mainForRuntime.roleIKMgr -- maybe nil
