    self.roleAnimatorMgr = self.idolLive3D_InteractiveManager.roleAnimatorMgr
    self.baseJson = self.idolLive3D_InteractiveManager.baseJson
    self.roleAnimator = roleAnimator_
    self.iState = interactiveState_ -- json
    self.currentClipId = nil
    self.blockerKey = "superTimeLine_" ..  self.iState. name
    

    -- 客制 自由轨道相机 json
    for _,clip in pairs(self.iState.allClips) do
        if isNotNull(clip.customFreeTrack) and clip.customFreeTrack.isUse == true then            
            clip.customFreeTrack.freeTrackJson = IdolLive3D_Utils.LoadJsonSync( clip.customFreeTrack.freeTrackJsonPath ) -- 比如: "Presets/IdolLive3D/FreeTrack/test1.json"
            clip.customFreeTrack.freeCameraTrackNodeParamsManager = IdolLive3D_FreeCameraTrackNodeParamsManager.New(clip.customFreeTrack.freeTrackJsonFileName, clip.customFreeTrack.freeTrackJson ) 
        end
    end

    -- 本 superTimeline 指定的脚本:
    self.scriptEnv = nil
    if string.isEmpty( self.iState.luaPath ) == false then 
        local path = "Game.IdolLive3D.Interactive.Customs." .. self.iState.luaPath
        print( "SuperTimeLine 脚本: " .. tostring(path) )
        local Script = import(path) -- "Game.IdolLive3D.Interactive.Customs.SuperTimeline_10302150"
        self.scriptEnv = Script.New(self)
    end 

    self.timelineEnvMaps = {} -- !! 注意, 现在是多层 map
    for clipId,tfs in pairs(timelineTFMaps_) do 
        local clipJson = self:_FindClipJson(clipId)
        self.timelineEnvMaps[clipId] = checkTable(self.timelineEnvMaps[clipId])

        -- 数据检测:
        if clipJson.clipType == IdolLive3D_StatesV2.SuperTimelineClipType.Normal then 
            if isNull(tfs.main) or isNotNull(tfs.fakeIK) or isNotNull(tfs.loopFakeIK) then 
                printError("异常, 普通 superTimeline clip 中, 某些 anim 数据异常")
            end 
        elseif clipJson.clipType == IdolLive3D_StatesV2.SuperTimelineClipType.FakeIK then 
            if isNotNull(tfs.main) or isNull(tfs.fakeIK) or isNull(tfs.loopFakeIK) then 
                printError("异常, fakeIK superTimeline clip 中, 某些 anim 数据异常")
            end 
        else 
            printError("异常 clipJson.clipType = " ..tostring(clipJson.clipType))
        end 

        -- 装填:
        if isNotNull(tfs.main) then 
            self.timelineEnvMaps[clipId].main           = IdolLive3D_TimeLineStateV2.New( self, clipId, clipJson, self.roleAnimator, tfs.main)         
        end 
        if isNotNull(tfs.fakeIK) then 
            self.timelineEnvMaps[clipId].fakeIK         = IdolLive3D_TimeLineStateV2.New( self, clipId, clipJson, self.roleAnimator, tfs.fakeIK) 
        end
        if isNotNull(tfs.loopFakeIK) then 
            self.timelineEnvMaps[clipId].loopFakeIK     = IdolLive3D_TimeLineStateV2.New( self, clipId, clipJson, self.roleAnimator, tfs.loopFakeIK)     
        end
    end

    self.EventSimpleTapInAnyTime  = Events.AddListener(IdolLive3D_States.EventSimpleTapInAnyTime, Bind(self, self._OnSimpleTapInAnyTime))

    ---
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        --[Live3D_CustomEvents.TimelineMarker] = Bind(self, self.OnTimelineMarker)
    })

    ---
    self.lastRefreshTime = 0
    self.isPlaying = false
    self.isStartFullScreenFXDadeIn = false
    self.isInit = true
end



