        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
end


function IdolLive3D_SuperTimeLineStateV2:OnDestroy()

    if UIRaycastBlocker:ContainsCondition(self.blockerKey)  then
        printError("ContainsCondition: "..tostring(self.blockerKey)) 
        UIRaycastBlocker:RemoveCondition(self.blockerKey) ---
    end 

    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end

    if isNotNull(self.scriptEnv) then 
        self.scriptEnv:Delete()
    end 

    CoStop(self.co_2)
    self.co_2 = nil
    CoStop(self.co_3)
    self.co_3 = nil

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end




