---@return boolean @ 若发现 autoLeaveInfo 并自动触发了它, 返回 true;
function IdolLive3D_SuperTimeLineStateV2:UpdateLeaveInfos( clipJson, timelineEnv )
    local leaveInfosNum = table.count(clipJson.leaveInfos)
    if leaveInfosNum > 0 then
        if isNotNull(clipJson.autoLeaveInfo) then 

            local isTimesOut = false
            if clipJson.fullScreenBlack.isUsed == true then 
                isTimesOut = timelineEnv.play.totalTime > clipJson.fullScreenBlack.fullTime
            else 
                isTimesOut = timelineEnv.play.loopInteger > 0
            end 
            -- 自动退出 superTimeline:
            -- 离场:
            if isTimesOut == true then
                print("自动 退出 superTimeline" )
                self.isPlaying = false
                if self:_TryCallCustomScriptFunc( CustomFuncs.SelfEndPLay, clipJson, timelineEnv ) then
                    ---
                else 
                    self:EndPLay( clipJson.autoLeaveInfo )
                end
                return true
            end
        else 
            -- 满足条件后才能 leave:
            if self:_TryCallCustomScriptFunc( CustomFuncs.CheckEachFrameForLeave, clipJson, timelineEnv ) then 
                ---
            else
                -- 本脚本已经能自动响应点击了
            end
        end 
    end
    return false
end


---@return boolean @ 若发现 autoNextClipInfo 并自动触发了它, 返回 true;
function IdolLive3D_SuperTimeLineStateV2:UpdateNextClipInfos( clipJson, timelineEnv )
    local nextClipInfosNum = table.count(clipJson.nextClipInfos)
    if nextClipInfosNum > 0 then
        if isNotNull(clipJson.autoNextClipInfo) then 

            local isTimesOut = false
            if clipJson.fullScreenBlack.isUsed == true then 
                isTimesOut = timelineEnv.play.totalTime > clipJson.fullScreenBlack.fullTime
            else 
                isTimesOut = timelineEnv.play.loopInteger > 0
            end 
            -- 自动进入下一个 clip:
            if isTimesOut == true then
                print("自动 跳入下一个 clip" )
                self:PlayClip( clipJson.autoNextClipInfo.clipId, false )
                return true
            end
        else 
            -- 满足条件后才能 to next clip:
            if self:_TryCallCustomScriptFunc( CustomFuncs.CheckEachFrameForNextClip, clipJson, timelineEnv ) then 
                ---
            else 
                -- 本脚本已经能自动响应点击了
            end
        end 
    end
    return false
end




-- 被外部调用; 响应 markers:
function IdolLive3D_SuperTimeLineStateV2:OnTimelineMarker( params ) 
    --printError("marker - " .. tostring(params.markerName))
    if params.markerName == string.lower("FullScreenFXFadeIn") then 
        local duration = params.timelineEnv.play.duration - params.markerTime
        if duration < 0.01 then 
            printError("marker FullScreenFXFadeIn 不该太靠近 timeline 的终点")
            duration = 0.01
        end 
        self.idolLive3D_InteractiveManager.fullScreenFXEnv:StartFadeIn( duration )
        self.isStartFullScreenFXDadeIn = true 


    elseif params.markerName == string.lower("FullScreenFXFadeOut") then 

        local duration = 0.1
        self.idolLive3D_InteractiveManager.fullScreenFXEnv:StartFadeOut( duration )
        self.isStartFullScreenFXDadeIn = false 

    end
    ---
    self:_TryCallCustomScriptFunc( CustomFuncs.OnTimelineMarker, params )
end


