-- 开始整段 superTimeline:
function IdolLive3D_SuperTimeLineStateV2:Play()
    if self.isInit ~= true then 
        return
    end

    local enterFullScreenFXPair = self.iState.enterFullScreenFXPair
    if enterFullScreenFXPair.isUsed == true then 

        local fadeInTime  = Mathf.Max( checkNumber(enterFullScreenFXPair.fadeInTime), 0 )
        local fullTime    = Mathf.Max( checkNumber(enterFullScreenFXPair.fullTime), 0 )
        local fadeOutTime = Mathf.Max( checkNumber(enterFullScreenFXPair.fadeOutTime), 0 )

        if UIRaycastBlocker:ContainsCondition(self.blockerKey)  then 
            printError("正在 Play 协程 中, 放弃本次 play 协程")
            return
        end 

        CoStop(self.co_3)
        self.co_3 = CoStart(function()
            UIRaycastBlocker:AddCondition(self.blockerKey) ---
            -- -1-
            cs_coroutine.yield_return( self.idolLive3D_InteractiveManager.fullScreenFXEnv:FadeIn(fadeInTime) ) 
            cs_coroutine.yield_return( self.idolLive3D_InteractiveManager.fullScreenFXEnv:WaitTargetState( IdolLive3D_States.FullScreenFXState.Show ) ) -- 等待 fadeIn 结束
            -- -2-
            coroutine.yield(Yielders.EndOfFrame)
            self:_Play()
            coroutine.yield(Yielders.EndOfFrame)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds( fullTime ))
            -- -3-
            cs_coroutine.yield_return( self.idolLive3D_InteractiveManager.fullScreenFXEnv:FadeOut(fadeOutTime) )       
            ---
            UIRaycastBlocker:RemoveCondition(self.blockerKey) ---
        end)
    else 
        self:_Play()
    end 
end



function IdolLive3D_SuperTimeLineStateV2:_Play()
    print("进入 super timeline")
    self:_TryCallCustomScriptFunc(CustomFuncs.StartPlay)

    self.isPlaying = true
    self.currentClipId = nil
    self.isStartFullScreenFXDadeIn = false
    self:PlayClip( self.iState.firstClipId , true )
    ---
    self.RoleColliderMgr:IntoNewState( self.iState.allConditionKeys )
end


