-- !!! play clip 的唯一入口:
---@param newClipId_ string 
---@param isFirstClip_ boolean
function IdolLive3D_SuperTimeLineStateV2:PlayClip( newClipId_, isFirstClip_ )
    --printError("PlayClip: " .. tostring(newClipId_))

    local lastClipId = self.currentClipId -- cache
    self.currentClipId = newClipId_
    local newClipJson = self:_FindClipJson(newClipId_)

    ---
    local timelineEnv = nil
    if newClipJson.clipType == IdolLive3D_StatesV2.SuperTimelineClipType.Normal then 
        timelineEnv = self.timelineEnvMaps[self.currentClipId].main
    elseif newClipJson.clipType == IdolLive3D_StatesV2.SuperTimelineClipType.FakeIK then 
        timelineEnv = self.timelineEnvMaps[self.currentClipId].loopFakeIK
    else 
        printError("异常 newClipJson.clipType = " .. tostring(newClipJson.clipType)) -- !!!!! 
        return
    end 

    -------
    self.idolLive3D_InteractiveManager:PlayVideoSubtitle(newClipJson.videoSubtitle) -- 播放字幕

    -- 登记本 clip 内的 音效
    self.idolLive3D_InteractiveManager:RegistSounds( newClipJson, true, function()
        return timelineEnv.play
    end )

    if isNotNull(self.roleIKMgr) then 
        self.roleIKMgr:IntoNewState( newClipJson.IKParams )
    end

    self.uiMain:IntoNewState( newClipJson.uiMgr )

    self.idolLive3D_InteractiveManager:AddToQueue( self.iState, {clipId = newClipId_, clipJson = newClipJson} ) 

    if isNotNull(lastClipId) then 
        self:_EndClip( lastClipId )
    end 

    -- Custom 自由轨道相机
    if isNotNull(newClipJson.customFreeTrack) and newClipJson.customFreeTrack.isUse == true then 
        self.cameraEnv.freeCameraMgr:SwitchFreeCamera_PosFree( 
            newClipJson.customFreeTrack.freeTrackCenterPos, 
            newClipJson.customFreeTrack.freeCameraActiveSpatialRange, 
            self.cameraEnv:GetFreeCameraSpatialParams(), -- !! 具体机位会在 后面设置, 此时写个临时值
            newClipJson.customFreeTrack.freeCameraTrackNodeParamsManager
        )
    end

    IdolLive3D_BaseParamsJsonDataV2.HandleSceneNodes( newClipJson.sceneNodesMgr, true )
    --
    self:_TryCallCustomScriptFunc(CustomFuncs.AfterPlayClip, newClipJson, timelineEnv)


    if isFirstClip_ == true then 
        self.cameraEnv:SwitchToCameraMode_FirstToFreeAuto_ThenToTimeLine( timelineEnv, self.iState, newClipJson.easeInBlendTime )
    else 
        assert( isNotNull(lastClipId) )
        local lastTimelineEnv = self.timelineEnvMaps[lastClipId].main
        lastTimelineEnv:Hide()
        self.cameraEnv:ToNextTimeline( timelineEnv, newClipJson.easeInBlendTime, newClipJson.initFreeCameraSpatialParams )
    end 
end


