-- ================================ EndPLay ==========================================

-- 结束整个 superTimeline:
function IdolLive3D_SuperTimeLineStateV2:EndPLay( leaveInfo_ )
    local clipJson = self:_FindClipJson(self.currentClipId)

    local __isFullScreenFXLeave__ = leaveInfo_.leaveMode == IdolLive3D_States.SuperTimelineLeaveMode.FullScreenFX
    ---
    local endCBDatas = {
        iState = self.iState, 
        clipJson = clipJson,
        leaveInfo = leaveInfo_,
    }
    ---
    CoStop(self.co_2)
    self.co_2 = CoStart(function()

        self.isPlaying = false

        --- 全屏 fadeIn:
        if __isFullScreenFXLeave__ then 
            if self.isStartFullScreenFXDadeIn == false then 
                self.isStartFullScreenFXDadeIn = true
                -- 只有当 leave timeline clip marker 中 没有 设置 "FullScreenFXFadeIn" 时, 此处才被执行:
                cs_coroutine.yield_return( self.idolLive3D_InteractiveManager.fullScreenFXEnv:FadeIn() ) 
            end 
            cs_coroutine.yield_return( self.idolLive3D_InteractiveManager.fullScreenFXEnv:WaitTargetState( IdolLive3D_States.FullScreenFXState.Show ) ) -- 等待 fadeIn 结束
        end 

        --- 客制cb点:
        self:_TryCallCustomScriptFunc( CustomFuncs.BeforeEndProcess, endCBDatas )

        self:_EndClip( self.currentClipId )
        IdolLive3D_BaseParamsJsonDataV2.HandleSceneNodes( clipJson.sceneNodesMgr, false )

        -- Hide All timelineEnv:
        for _,timelineEnv in pairs(self.timelineEnvMaps[self.currentClipId]) do 
            if isNotNull(timelineEnv) then 
                timelineEnv:Hide()
            end 
        end 

        Events.Broadcast(Constants.EventNames.Live3DIsInTimelineState, false)
        IdolLive3D_States.isPlayingTimeline = false

        --- vcam blend:
        if __isFullScreenFXLeave__ then 
            IdolLive3D_Utils.SetVCamBlendMode( CinemachineBlendDefinition.Style.EaseInOut, 0 ) -- 瞬切
        else 
            IdolLive3D_Utils.SetVCamBlendMode( CinemachineBlendDefinition.Style.EaseInOut, checkNumber(leaveInfo_.easeOutBlendTime) )
        end 


        if isNotNull(self.cameraEnv.cachedTimelineVCam) then                
            -- 基于旧vcam位置, 修正 freeVCam 机位;
            self.cameraEnv.freeCameraMgr:FreeCameraCloseToTgtPos( self.cameraEnv.cachedTimelineVCam.transform.position, leaveInfo_.finishedFreeCameraSpatialParams )     
            -- 固定机位自由相机 清空旋转值:
            self.cameraEnv.freeCameraMgr:PosLockedCameraResetImmediately()       
            ---
            self.cameraEnv.freeCameraMgr:SetPriority( IdolLive3D_States.VCamPriority.High )
            self.cameraEnv.cachedTimelineVCam.Priority = IdolLive3D_States.VCamPriority.Low

            if __isFullScreenFXLeave__ then
                -- 
            else 
                -- 等待 timelineVCam -> freeVCam 过度结束
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds( checkNumber(leaveInfo_.easeOutBlendTime) ))
            end
            -- 等完之后再设置, 确保在相机切换阶段, 玩家依然无法操纵 自由轨道相机
            self.cameraEnv:SetCachedTimelineVCam( nil )
        else 
            -- 说明最后一个 clip 没有 vcam, 无需相机切换操作;
        end
        ---
        self.cameraEnv:SwitchToCameraMode_FreeManual()

        --- 客制cb点:
        self:_TryCallCustomScriptFunc( CustomFuncs.AfterEndProcess, endCBDatas )
    
        ---
        local tgtStageJson = self.baseJson:GetStage( leaveInfo_.tgtStageName ) -- 要去的 stage; 允许是当前的那个
        if __isFullScreenFXLeave__ then 
            cs_coroutine.yield_return( self.idolLive3D_InteractiveManager:WaitUntilIdleState() ) -- 几乎不用等待
            ---
            
            self.idolLive3D_InteractiveManager:ForceToTargetStage( tgtStageJson, IdolLive3D_States.StageJumpType.FromSuperTimeline )
        else
            self.RoleColliderMgr:IntoNewState( tgtStageJson.allTouchKeys )

            if isNotNull(self.roleIKMgr) then 
                self.roleIKMgr:IntoNewState( tgtStageJson.idleState.IKParams )
            end

            self.uiMain:IntoNewState( tgtStageJson.uiMgr )
        end
    end)
end


