--@return boolean @ 是否找到目标函数;
function IdolLive3D_SuperTimeLineStateV2:_TryCallCustomScriptFunc( funcName_, ... )
    if IdolLive3D_Utils.IsKeyValid(funcName_) == false then 
        printError("参数异常: " .. tostring(funcName_))
        return false
    end 
    if isNotNull(self.scriptEnv) and type(self.scriptEnv[funcName_]) == "function" then 
        self.scriptEnv[funcName_]( self.scriptEnv, ... )
        return true
    else 
        return false
    end 
end


function IdolLive3D_SuperTimeLineStateV2:_FindClipJson( clipId_ )
    local clipJson = self.iState.allClips[clipId_]
    assert( isNotNull(clipJson) )
    return clipJson
end


---@param idStr_ string @ role 碰撞体 ID组件的 string 参数
function IdolLive3D_SuperTimeLineStateV2:_OnSimpleTapInAnyTime( idStr_ )
    if self.isInit ~= true then 
        return
    end 
    if self.isPlaying ~= true then 
        return
    end 
    -----
    if (Time.time - self.lastRefreshTime) > effectiveDuration then 
        --printError("不在有效时间窗口内")
        return
    end 
    ---
    local touchStr = string.lower(tostring(idStr_))
    local clipJson = self:_FindClipJson(self.currentClipId)
    ---
    if #touchStr == 0 then 
        return
    end 
    ---
    if table.count(clipJson.leaveInfosMap) > 0 then 
        --- 优先捕捉有具体名字的:
        local leaveInfo = clipJson.leaveInfosMap[touchStr]
        if isNotNull(leaveInfo) then 
            self:EndPLay( leaveInfo )
        else 
            -- "_any_", "_all_" 这两种特殊的:
            local allNode = clipJson.leaveInfosMap[IdolLive3D_StatesV2.allSimpleTapName] -- "_all_"
            if isNotNull(allNode) then 
                self:EndPLay( allNode )
            else 
                if touchStr ~= IdolLive3D_StatesV2.emptySimpleTapName then 
                    local anyNode = clipJson.leaveInfosMap[IdolLive3D_StatesV2.anySimpleTapName] -- "_any_"
                    if isNotNull(anyNode) then 
                        self:EndPLay( anyNode )
                    end
                end 
            end
        end 
        return
    end 
    ---
    if table.count(clipJson.nextClipInfosMap) > 0 then 
        --- 优先捕捉有具体名字的:
        local nextClipInfo = clipJson.nextClipInfosMap[touchStr]
        if isNotNull(nextClipInfo) then 
            self:PlayClip( nextClipInfo.clipId, false )
        else 
            -- "_any_", "_all_" 这两种特殊的:
            local allNode = clipJson.nextClipInfosMap[IdolLive3D_StatesV2.allSimpleTapName] -- "_all_"
            if isNotNull(allNode) then 
                self:PlayClip( allNode.clipId, false )
            else 
                if touchStr ~= IdolLive3D_StatesV2.emptySimpleTapName then 
                    local anyNode = clipJson.nextClipInfosMap[IdolLive3D_StatesV2.anySimpleTapName] -- "_any_"
                    if isNotNull(anyNode) then 
                        self:PlayClip( anyNode.clipId, false )
                    end
                end 
            end
        end 
        return
    end     
end




return IdolLive3D_SuperTimeLineStateV2
